package agentstate

import (
	"io"
	"os"
	"path/filepath"
	"testing"
)

// TestPreMovePopulatedDatabaseSurvivesOpenAndReopen verifies that the current
// owner repositories preserve a populated database generated by the integration
// source before the Identity and Inventory persistence moves.
func TestPreMovePopulatedDatabaseSurvivesOpenAndReopen(t *testing.T) {
	source, err := os.Open("testdata/pr095b-baseline-populated-v14.db")
	if err != nil {
		t.Fatal(err)
	}
	defer source.Close()
	path := filepath.Join(t.TempDir(), "state.db")
	destination, err := os.Create(path)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := io.Copy(destination, source); err != nil {
		destination.Close()
		t.Fatal(err)
	}
	if err := destination.Close(); err != nil {
		t.Fatal(err)
	}

	for open := 1; open <= 2; open++ {
		store := newTestSQLiteStore(path)
		loaded, err := store.Load()
		if err != nil {
			t.Fatalf("open %d load Agent state: %v", open, err)
		}
		if loaded.DesiredGeneration != 8 || loaded.ActivatedGeneration != 7 || loaded.AppliedGeneration != 7 || !loaded.Dependencies["host"].Enabled {
			t.Fatalf("open %d Agent state changed: %+v", open, loaded)
		}
		installationID, err := newTestIdentityStore(path).EnsureInstallationID(mustInstallationID(t, "123e4567-e89b-12d3-a456-426614174000"))
		if err != nil || installationID.String() != "123e4567-e89b-12d3-a456-426614174000" {
			t.Fatalf("open %d installation identity=%s err=%v", open, installationID, err)
		}
		attempt, err := newTestEnrollmentStore(path).LoadAttempt()
		if err != nil {
			t.Fatalf("open %d load enrollment attempt: %v", open, err)
		}
		if attempt.Payload.AttemptID != "10000000-0000-4000-8000-000000000001" || attempt.Payload.Installation.ID != installationID.String() || attempt.Status != "pending" {
			t.Fatalf("open %d enrollment attempt changed: %+v", open, attempt)
		}
		desired, err := store.IntegrationRepository().Snapshot()
		if err != nil || desired.Revision != 1 || len(desired.Instances) != 1 || desired.Instances[0].ID != "redis-main" {
			t.Fatalf("open %d desired state=%+v err=%v", open, desired, err)
		}
		inventory, err := store.InventoryRepository().Snapshot()
		if err != nil {
			t.Fatalf("open %d load inventory: %v", open, err)
		}
		if inventory.Revision != 1 || len(inventory.Resources) != 1 || inventory.Resources[0].Key.ProviderResourceID != "container-a" || len(inventory.Providers) != 1 || inventory.Providers[0].LastErrorCode != "fixture_daemon_unavailable" {
			t.Fatalf("open %d inventory changed: %+v", open, inventory)
		}
		db, err := store.open()
		if err != nil {
			t.Fatalf("open %d database: %v", open, err)
		}
		var version int
		if err := db.QueryRow(`SELECT MAX(version) FROM schema_migrations`).Scan(&version); err != nil {
			db.Close()
			t.Fatal(err)
		}
		if err := db.Close(); err != nil {
			t.Fatal(err)
		}
		if version != 14 {
			t.Fatalf("open %d schema version=%d, want 14", open, version)
		}
	}
}
